"""Sample Python module for testing."""


def greet(name: str) -> str:
    """Return a greeting."""
    return f"Hello, {name}"


class Calculator:
    """A simple calculator."""

    def add(self, a: int, b: int) -> int:
        """Add two numbers."""
        return a + b


def farewell(name: str) -> str:
    """Say goodbye."""
    return f"Goodbye, {name}"
